import { fileURLToPath } from 'node:url';
import { Logger, type OnBeforeInit } from '@dunx/core';
import { migrate } from 'drizzle-orm/bun-sql/migrator';
import { Db } from './db.js';

/** drizzle-kit's output, beside src/ in the repository and in the image. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

/**
 * Applies the committed migrations in drizzle/ (generated by `bun run db:generate`, journaled by drizzle in its own
 * `drizzle.__drizzle_migrations` table), in `onBeforeInit` so every `onInit` in the app (the board catalog's upsert
 * among them) already sees the current schema. A migration that fails fails the boot; the schema is never half-new.
 *
 * One node runs at a time on the Pi. Several replicas starting together would each try the same migration and all but
 * one fail on it and restart, so a fleet would migrate from a release job instead.
 */
export class Migrations implements OnBeforeInit {
  constructor(
    private readonly db: Db,
    private readonly logger: Logger,
  ) {}

  async onBeforeInit(): Promise<void> {
    const started = performance.now();
    await migrate(this.db, { migrationsFolder: MIGRATIONS_FOLDER });
    this.logger.info('database migrated', { ms: Math.round(performance.now() - started) });
  }
}
